#!/usr/bin/env python3
"""Prepare inert image-author input bindings. No production files are written."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[6]
OUT = Path(__file__).resolve().parent
SOURCE = ROOT / 'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-07/biologie-neuro-twenty-one-current-continuation-author-v3/stage-02-current-twenty-one-native'
RAW = SOURCE / 'final-current21-whole-native-source-context-material-review-inputs.author.raw.json'
CASES = SOURCE / 'forty-two-complete-DEEN-reference-materials.current21.author-candidates.json'
WITNESSES = SOURCE / 'all21-selected-actual-frozen-source-witness-effective-file-bindings.author.json'

def bind(path):
    data = path.read_bytes()
    return {'path': str(path.relative_to(ROOT)), 'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}

def put(name, obj):
    path = OUT / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + '\n')

