COMMON = '''Use case: scientific-educational illustration for German upper-secondary biology.
Create one original landscape PNG, approximately 16:9. A warm, friendly hand-drawn comic learning illustration with clear slightly organic outlines, large welcoming colored forms, a soft ivory background and spacious composition. Friendly does not mean childish or anthropomorphic. Make the scientific mechanism clear using well separated structures and directional arrows. This is a bounded model example, not a task sheet or a full textbook page.
Critical display requirement: all essential labels and symbols must remain easily readable when the actual image width is 360 pixels, and at 680 pixels with maximum display height 448 pixels using object-contain. Use very large short German labels, preferably around 64 pixels high on a 1536-pixel-wide artwork. Never use tiny explanatory sentences, fine-print legends, decorative microtext or dense sterile tables. No header, footer, watermark, logo, goal identifier or branding. The requested German text must be correctly spelled. Favor visual relationships over text. Do not add extra scientific claims or captions.
'''

first = ['ce19', '1b38', 'e3fb', '04d7', 'ff1', 'e111', 'f628']
raw = json.loads(RAW.read_text())
cases = json.loads(CASES.read_text())['cases']
bindings = json.loads(WITNESSES.read_text())['records']
plans = []
for row in raw['wholeCurrent21CandidateNativeRows']:
    gid = row['goalId']
    prefix = next(k for k in DESIGNS if gid.startswith(k))
    family, composition, limit = DESIGNS[prefix]
    prompt = COMMON + '\nComposition and exact model:\n' + composition + '\n\nBoundaries:\n' + limit + '\n'
    prompt_path = OUT / 'prompts' / (gid + '.prompt.txt')
    prompt_path.parent.mkdir(exist_ok=True)
    prompt_path.write_text(prompt)
    item = {'goalId': gid, 'family': family, 'firstSeven': prefix in first,
        'status': 'author_plan_pending_generation', 'wholeStage02CandidateGoal': row['wholeCandidateGoal'],
        'completeReferenceCases': [c for c in cases if c['goalId'] == gid],
        'actualFrozenSourceWitnessEffectiveBindings': [b for b in bindings if b['goalId'] == gid],
        'compositionDe': composition, 'boundedScopeDe': limit, 'prompt': bind(prompt_path),
        'humanApproval': False, 'independentVisualApproval': False, 'strictCompletion': 0}
    if prefix == '080b':
        item['generationHold'] = 'Await possible concrete current P-case correction; outside first seven.'
    assert len(item['completeReferenceCases']) == 2
    plans.append(item)
assert len(plans) == 21 and sum(p['firstSeven'] for p in plans) == 7
put('current21-whole-goals-materials-source-bound-image-plans.author.raw.json', {
    'role': 'image author; not independent V reviewer or integration',
    'authoringMethod': 'ChatGPT/Codex builtin image generation, one call per asset; no API/CLI fallback',
    'licenseForOwnImageCandidates': 'CC-BY-4.0', 'inputs': [bind(RAW), bind(CASES), bind(WITNESSES)],
    'primaryOriginalsActuallyReadForFirstSeven': [bind(ROOT / 'curricula/DE/Gymnasium/input/BY/gymnasium/Biologie.json'), bind(ROOT / 'curricula/DE/Gymnasium/input/HE/upper-secondary/kerncurriculum_gymnasiale_oberstufe-biologie.pdf')],
    'sourceBounds': 'BY B13 basic/advanced and HE Q2.3 page 43 for these bounded models; whole national source closure is not claimed.',
    'families': sorted(set(p['family'] for p in plans)), 'plans': plans,
    'firstSevenOrder': [p['goalId'] for k in first for p in plans if p['goalId'].startswith(k)],
    'actualGoalCardCss': {'path': 'app/src/components/GoalCard.tsx', 'image': 'display:block;height:auto;max-height:448px;width:100%;object-fit:contain'},
    'displayWidths': [360, 680], 'activeWrites': False, 'runtimeWrites': False, 'registryWrites': False,
    'independentVisualApproval': False, 'humanApproval': False, 'newStrictCompletion': 0,
    'allOriginalSourceHoldsPreserved': True})
print(json.dumps({'plans': len(plans), 'firstSeven': 7, 'families': len(set(p['family'] for p in plans)), 'output': str(OUT.relative_to(ROOT))}))
